package com.johnny.hotel.repair;import com.johnny.hotel.task.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import java.time.*;import java.time.temporal.ChronoUnit;import static com.johnny.hotel.service.support.BillingRules.one;
@Component@RequiredArgsConstructor public class RepairTaskObserver implements TaskLifecycleObserver{private final RepairOrderMapper repairs;private final Clock clock;@Override public void acknowledged(HotelTask task,Todo todo,Long actor){if(task.getTaskType()==TaskType.ROOM_REPAIR.getCode())one(repairs.start(task.getId(),LocalDateTime.now(clock).truncatedTo(ChronoUnit.MICROS)));}}
